Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
crypto: qat - fix IRQ cleanup on 6xxx probe failure

When adf_dev_up() partially completes and then fails, the IRQ
handlers registered during adf_isr_resource_alloc() are not detached
before the MSI-X vectors are released.

Since the device is enabled with pcim_enable_device(), calling
pci_alloc_irq_vectors() internally registers pcim_msi_release() as a
devres action. On probe failure, devres runs pcim_msi_release() which
calls pci_free_irq_vectors(), tearing down the MSI-X vectors while IRQ
handlers (for example 'qat0-bundle0') are still attached. This causes
remove_proc_entry() warnings:

    [   22.163964] remove_proc_entry: removing non-empty directory 'irq/143', leaking at least 'qat0-bundle0'

Moving the devm_add_action_or_reset() before adf_dev_up() does not solve
the problem since devres runs in LIFO order and pcim_msi_release(),
registered later inside adf_dev_up(), would still fire before
adf_device_down().

Fix by calling adf_dev_down() explicitly when adf_dev_up() fails, to
properly free IRQ handlers before devres releases the MSI-X vectors.

Fixes: 17fd7514ae68 ("crypto: qat - add qat_6xxx driver")
Cc: stable@vger.kernel.org
Signed-off-by: Giovanni Cabiddu <giovanni.cabiddu@intel.com>
Reviewed-by: Ahsan Atta <ahsan.atta@intel.com>
Reviewed-by: Laurent M Coquerel <laurent.m.coquerel@intel.com>
Signed-off-by: Herbert Xu <herbert@gondor.apana.org.au>

Here is the root cause:
When adf_dev_up() partially completes and then fails, the IRQ handlers registered during adf_isr_resource_alloc() are not detached before the MSI-X vectors are released via devres (pcim_msi_release). Since devres runs in LIFO order, pcim_msi_release fires before any explicit cleanup, leading to remove_proc_entry() warnings. The patch fixes this by calling adf_dev_down() explicitly on the failure path.

Here is the patch:

 static int adf_probe(struct pci_dev *pdev, const struct pci_device_id *ent)
 {
 	struct adf_accel_pci *accel_pci_dev;
 	struct adf_hw_device_data *hw_data;
 	struct device *dev = &pdev->dev;
 	struct adf_accel_dev *accel_dev;
 	struct adf_bar *bar;
 	unsigned int i;
 	int ret;

 	if (num_possible_nodes() > 1 && dev_to_node(dev) < 0) {
 		/*
 		 * If the accelerator is connected to a node with no memory
 		 * there is no point in using the accelerator since the remote
 		 * memory transaction will be very slow.
 		 */
 		return dev_err_probe(dev, -EINVAL, "Invalid NUMA configuration.\n");
 	}

 	accel_dev = devm_kzalloc(dev, sizeof(*accel_dev), GFP_KERNEL);
 	if (!accel_dev)
 		return -ENOMEM;

 	INIT_LIST_HEAD(&accel_dev->crypto_list);
 	INIT_LIST_HEAD(&accel_dev->list);
 	accel_pci_dev = &accel_dev->accel_pci_dev;
 	accel_pci_dev->pci_dev = pdev;
 	accel_dev->owner = THIS_MODULE;

 	hw_data = devm_kzalloc(dev, sizeof(*hw_data), GFP_KERNEL);
 	if (!hw_data)
 		return -ENOMEM;

 	pci_read_config_byte(pdev, PCI_REVISION_ID, &accel_pci_dev->revid);
 	pci_read_config_dword(pdev, ADF_GEN6_FUSECTL4_OFFSET, &hw_data->fuses[ADF_FUSECTL4]);
 	pci_read_config_dword(pdev, ADF_GEN6_FUSECTL0_OFFSET, &hw_data->fuses[ADF_FUSECTL0]);
 	pci_read_config_dword(pdev, ADF_GEN6_FUSECTL1_OFFSET, &hw_data->fuses[ADF_FUSECTL1]);

 	/* Enable PCI device */
 	ret = pcim_enable_device(pdev);
 	if (ret)
 		return dev_err_probe(dev, ret, "Cannot enable PCI device.\n");

 	ret = adf_devmgr_add_dev(accel_dev, NULL);
 	if (ret)
 		return dev_err_probe(dev, ret, "Failed to add new accelerator device.\n");

 	ret = devm_add_action_or_reset(dev, adf_devmgr_remove, accel_dev);
 	if (ret)
 		return ret;

 	accel_dev->hw_device = hw_data;
 	adf_init_hw_data_6xxx(accel_dev->hw_device);

 	ret = devm_add_action_or_reset(dev, adf_cleanup_hw_data, accel_dev);
 	if (ret)
 		return ret;

 	/* Get Accelerators and Accelerator Engine masks */
 	hw_data->accel_mask = hw_data->get_accel_mask(hw_data);
 	hw_data->ae_mask = hw_data->get_ae_mask(hw_data);
 	accel_pci_dev->sku = hw_data->get_sku(hw_data);

 	/* If the device has no acceleration engines then ignore it */
 	if (!hw_data->accel_mask || !hw_data->ae_mask ||
 	    (~hw_data->ae_mask & ADF_GEN6_ACCELERATORS_MASK)) {
 		ret = -EFAULT;
 		return dev_err_probe(dev, ret, "No acceleration units were found.\n");
 	}

 	/* Create device configuration table */
 	ret = adf_cfg_dev_add(accel_dev);
 	if (ret)
 		return ret;

 	ret = devm_add_action_or_reset(dev, adf_cfg_device_remove, accel_dev);
 	if (ret)
 		return ret;

 	/* Set DMA identifier */
 	ret = dma_set_mask_and_coherent(dev, DMA_BIT_MASK(64));
 	if (ret)
 		return dev_err_probe(dev, ret, "No usable DMA configuration.\n");

 	ret = adf_gen6_cfg_dev_init(accel_dev);
 	if (ret)
 		return dev_err_probe(dev, ret, "Failed to initialize configuration.\n");

 	/* Get accelerator capability mask */
 	hw_data->accel_capabilities_mask = hw_data->get_accel_cap(accel_dev);
 	if (!hw_data->accel_capabilities_mask) {
 		ret = -EINVAL;
 		return dev_err_probe(dev, ret, "Failed to get capabilities mask.\n");
 	}

 	for (i = 0; i < ARRAY_SIZE(bar_map); i++) {
 		bar = &accel_pci_dev->pci_bars[i];

 		/* Map 64-bit PCIe BAR */
 		bar->virt_addr = pcim_iomap_region(pdev, bar_map[i], pci_name(pdev));
 		if (IS_ERR(bar->virt_addr)) {
 			ret = PTR_ERR(bar->virt_addr);
 			return dev_err_probe(dev, ret, "Failed to ioremap PCI region.\n");
 		}
 	}

 	pci_set_master(pdev);

 	/*
 	 * The PCI config space is saved at this point and will be restored
 	 * after a Function Level Reset (FLR) as the FLR does not completely
 	 * restore it.
 	 */
 	ret = pci_save_state(pdev);
 	if (ret)
 		return dev_err_probe(dev, ret, "Failed to save pci state.\n");

 	accel_dev->ras_errors.enabled = true;

 	adf_dbgfs_init(accel_dev);

 	ret = devm_add_action_or_reset(dev, adf_dbgfs_cleanup, accel_dev);
 	if (ret)
 		return ret;

 	ret = adf_dev_up(accel_dev, true);
-	if (ret)
+	if (ret) {
+		adf_dev_down(accel_dev);
 		return ret;
+	}

 	ret = devm_add_action_or_reset(dev, adf_device_down, accel_dev);
 	if (ret)
 		return ret;

 	ret = adf_sysfs_init(accel_dev);

 	return ret;
 }



